"use client";

export function MeshGradientTailwind({ children }: { children?: React.ReactNode }) {
  const blobs = [
    "left-[5%] top-[0%] bg-[#ff5c9a] animate-[spin_22s_linear_infinite]",
    "right-[0%] top-[-5%] bg-[#7c5cff] animate-[spin_27s_linear_infinite_reverse]",
    "right-[15%] bottom-[-15%] bg-[#00c2ff] animate-[spin_31s_linear_infinite]",
    "left-[5%] bottom-[-20%] bg-[#ffb36b] animate-[spin_25s_linear_infinite_reverse]",
  ];
  return (
    <div className="relative isolate flex h-[360px] w-full items-center justify-center overflow-hidden rounded-[20px] border border-zinc-800 bg-[#0c0a1f]">
      <div aria-hidden className="absolute -inset-[12%] blur-[70px]">
        {blobs.map((b, i) => (
          <div key={i} className={"absolute aspect-square h-[65%] origin-[65%_35%] rounded-full mix-blend-screen motion-reduce:animate-none " + b} />
        ))}
      </div>
      <div className="relative text-center">
        {children ?? (
          <>
            <h3 className="text-3xl font-bold tracking-tight text-zinc-50">Mesh Gradient</h3>
            <p className="mt-2 text-sm text-zinc-400">Soft color fields drifting on independent loops.</p>
          </>
        )}
      </div>
    </div>
  );
}
